189	  } catch (error) {
190	    logger.warn(
191	      `Failed to fetch traces for output ${evalRecord.id}; traces omitted from export: ${error}`,
192	    );
193	  }
194	
195	  const output: OutputFile = {
196	    evalId: evalRecord.id,
197	    results: summary,
198	    config: redactedConfig,
199	    shareableUrl,
200	    metadata: createOutputMetadata(evalRecord),
201	    ...(evalRecord.vars?.length > 0 && { vars: [...evalRecord.vars] }),
202	    ...(evalRecord.runtimeOptions && {
203	      runtimeOptions: sanitizeRuntimeOptions(evalRecord.runtimeOptions),
204	    }),
205	    ...(traces && traces.length > 0 && { traces: projectTracesForOutput(traces) }),
206	  };
207	
208	  if (options.includeMedia) {
209	    const blobAssets = await exportBlobAssets(summary, output.traces);
210	    if (blobAssets.length > 0) {
211	      output.blobAssets = blobAssets;
212	    }
213	  }
214	
215	  return output;
216	}
