+<!doctype html>
+<html>
+  <head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <title>My Eval &lt;Report&gt;</title>
+    <style>
+      :root {
+        --pass: #1a7f37;
+        --fail: #ad0000;
+        --error: #9a6700;
+        --border: #d0d7de;
+        --muted: #57606a;
+      }
+      body {
+        font-family:
+          -apple-system,
+          BlinkMacSystemFont,
+          Segoe UI,
+          Roboto,
+          Helvetica,
+          Arial,
+          sans-serif;
+        margin: 0;
+        color: #1f2328;
+        background: #f6f8fa;
+      }
+      .page {
+        max-width: 1200px;
+        margin: 0 auto;
+        padding: 24px;
+      }
+      h1 {
+        margin: 0 0 4px;
