+      .summary {
+        display: flex;
+        gap: 16px;
+        margin: 20px 0;
+        flex-wrap: wrap;
+      }
+      .metric-card {
+        background: #fff;
+        border: 1px solid var(--border);
+        border-radius: 8px;
+        padding: 12px 20px;
+        min-width: 140px;
+      }
+      .metric-label {
+        margin: 0;
+        font-size: 13px;
+        color: var(--muted);
+      }
+      .metric-value {
+        margin: 4px 0 0;
+        font-size: 24px;
+        font-weight: 600;
+      }
+      .controls {
+        display: flex;
+        gap: 12px;
+        align-items: center;
+        margin-bottom: 16px;
+        flex-wrap: wrap;
+      }
+      .controls input,
+      .controls select {
+        padding: 8px 10px;
+        border: 1px solid var(--border);
+        border-radius: 6px;
+        font-size: 14px;
+      }
+      .visible-count {
+        color: var(--muted);
+        font-size: 13px;
+      }
+      .cell {
+        background: #fff;
+        border: 1px solid var(--border);
+        border-radius: 8px;
+        padding: 16px;
+        margin-bottom: 12px;
+      }
+      .cell-head {
+        display: flex;
+        align-items: center;
+        gap: 12px;
+        margin-bottom: 10px;
+      }
+      .status-pill {
+        display: inline-block;
+        padding: 2px 10px;
+        border-radius: 999px;
+        font-size: 12px;
+        font-weight: 700;
+        color: #fff;
+      }
+      .status-pill.pass {
+        background: var(--pass);
+      }
+      .status-pill.fail {
+        background: var(--fail);
+      }
+      .status-pill.error {
+        background: var(--error);
+      }
+      .score {
+        color: var(--muted);
+        font-size: 13px;
+      }
+      .cell-ref {
+        color: var(--muted);
+        font-size: 13px;
+        margin-left: auto;
+      }
+      .output-text {
+        white-space: pre-wrap;
+        word-break: break-word;
+        margin: 0 0 8px;
+      }
+      .reason {
+        color: var(--muted);
+        white-space: pre-wrap;
+        word-break: break-word;
+        margin: 0 0 8px;
+      }
+      .detail-link {
+        background: none;
+        border: none;
+        color: #0969da;
+        cursor: pointer;
+        padding: 0;
+        font-size: 14px;
+      }
+      .empty-state {
+        display: none;
+        padding: 24px;
+        text-align: center;
+        color: var(--muted);
+      }
+      .detail-drawer {
+        position: fixed;
+        top: 0;
+        right: 0;
+        width: 420px;
+        max-width: 90vw;
+        height: 100%;
+        background: #fff;
+        border-left: 1px solid var(--border);
+        box-shadow: -4px 0 16px rgba(0, 0, 0, 0.1);
+        transform: translateX(100%);
+        transition: transform 0.2s ease;
+        overflow-y: auto;
+        padding: 20px;
+        box-sizing: border-box;
+      }
+      .detail-drawer.open {
+        transform: translateX(0);
+      }
+      .detail-drawer h3 {
+        margin: 16px 0 6px;
+        font-size: 14px;
+        text-transform: uppercase;
+        color: var(--muted);
+      }
+      [data-variable-list] span {
+        display: block;
+        padding: 4px 0;
+        border-bottom: 1px solid var(--border);
+      }
+      .drawer-close {
+        float: right;
+        cursor: pointer;
+        border: none;
+        background: none;
+        font-size: 18px;
+      }
+    </style>
+  </head>
+  <body>
+    <div class="page">
+      <h1>My Eval &lt;Report&gt;</h1>
+
+      <div class="summary">
+        <div class="metric-card">
+          <p class="metric-label">Total Results</p>
+          <p class="metric-value">3</p>
+        </div>
+        <div class="metric-card">
+          <p class="metric-label">Pass Rate</p>
+          <p class="metric-value">33.3%</p>
+        </div>
+      </div>
+
+      <div class="controls">
+        <input
+          type="search"
+          placeholder="Search results…"
+          data-report-search
+          oninput="applyFilters()"
+        />
+        <select data-status-filter onchange="applyFilters()">
+          <option value="all">All statuses</option>
+          <option value="pass">Pass</option>
+          <option value="fail">Fail</option>
+          <option value="error">Error</option>
+        </select>
+        <span class="visible-count" data-visible-count></span>
+      </div>
+
+      <div class="results">
+        
+        <div
+          class="cell"
+          data-output-cell="true"
+          data-status="pass"
+          data-search="PASS 1.00  Looks good "
