+          <button type="button" class="detail-link" data-open-detail onclick="openDetail(this)">
+            View detail
+          </button>
+          <template data-detail-template>
+            <div class="detail-body">
+              <h2 class="detail-title">
+                Result detail - row 1, prompt 1
+              </h2>
+              <h3>Prompt</h3>
+              <pre class="detail-prompt">Say hi to {{input}}</pre>
+              <h3>Variables</h3>
+              <div data-variable-list>
+                
+                <div
+                  data-variable-item
+                  data-variable-name="input"
+                  data-variable-value="hi &amp; &lt;there&gt;"
+                ></div>
+                
+              </div>
+            </div>
+          </template>
+        </div>
+        
+        <div
+          class="cell"
+          data-output-cell="true"
+          data-status="error"
+          data-search="ERROR 0.00 provider timed out Evaluation failed provider timed out"
+        >
+          <div class="cell-head">
+            <span class="status-pill error"
+              >ERROR</span
+            >
+            <span class="score">Score 0.00</span>
+            <span class="cell-ref">row 2, prompt 1</span>
+          </div>
+          <p class="output-text"></p>
+          
+          <p class="reason">Evaluation failed</p>
+           
+          <p class="reason error-text">provider timed out</p>
+          
+          <button type="button" class="detail-link" data-open-detail onclick="openDetail(this)">
+            View detail
+          </button>
+          <template data-detail-template>
+            <div class="detail-body">
+              <h2 class="detail-title">
+                Result detail - row 2, prompt 1
+              </h2>
+              <h3>Prompt</h3>
+              <pre class="detail-prompt">Say bye</pre>
+              <h3>Variables</h3>
+              <div data-variable-list>
+                
+                <div
+                  data-variable-item
+                  data-variable-name="input"
+                  data-variable-value="bye"
+                ></div>
+                
+              </div>
+            </div>
+          </template>
+        </div>
+        
+        <div
+          class="cell"
+          data-output-cell="true"
+          data-status="fail"
+          data-search="FAIL 0.00   "
+        >
+          <div class="cell-head">
+            <span class="status-pill fail"
+              >FAIL</span
+            >
+            <span class="score">Score 0.00</span>
+            <span class="cell-ref">row 3, prompt 1</span>
+          </div>
+          <p class="output-text">nope</p>
+           
+          <button type="button" class="detail-link" data-open-detail onclick="openDetail(this)">
+            View detail
+          </button>
+          <template data-detail-template>
+            <div class="detail-body">
+              <h2 class="detail-title">
+                Result detail - row 3, prompt 1
+              </h2>
+              <h3>Prompt</h3>
+              <pre class="detail-prompt">p</pre>
+              <h3>Variables</h3>
+              <div data-variable-list>
+                
+                <div
+                  data-variable-item
+                  data-variable-name="input"
+                  data-variable-value="x"
+                ></div>
+                
+              </div>
+            </div>
+          </template>
+        </div>
+        
+      </div>
+
+      <div class="empty-state" data-empty-state>
+        No rows match the current search and status filters.
+      </div>
+    </div>
+
+    <aside class="detail-drawer" data-detail-drawer>
+      <button type="button" class="drawer-close" onclick="closeDetail()">×</button>
+      <div data-detail-content></div>
+    </aside>
+
+    <script>
+      // Populate the Variables section of the drawer lazily from the
+      // data-variable-name placeholders rendered inside the detail template.
+      function appendVariableDetails(trigger) {
+        var tpl = trigger.parentElement.querySelector('[data-detail-template]');
+        if (!tpl) {
+          return null;
+        }
+        var fragment = tpl.content.cloneNode(true);
+        var list = fragment.querySelector('[data-variable-list]');
+        if (list) {
+          var placeholders = list.querySelectorAll('[data-variable-item]');
+          list.innerHTML = '';
+          placeholders.forEach(function (placeholder) {
+            var name = placeholder.getAttribute('data-variable-name') || '';
+            var value = placeholder.getAttribute('data-variable-value') || '';
+            var span = document.createElement('span');
+            span.className = 'detail-variable-' + 'name';
+            span.textContent = name + ': ' + value;
+            list.appendChild(span);
+          });
+        }
+        return fragment;
+      }
+
+      function openDetail(trigger) {
+        var drawer = document.querySelector('[data-detail-drawer]');
+        var content = drawer.querySelector('[data-detail-content]');
+        content.innerHTML = '';
+        var fragment = appendVariableDetails(trigger);
+        if (fragment) {
+          content.appendChild(fragment);
+        }
+        drawer.classList.add('open');
+      }
+
+      function closeDetail() {
+        var drawer = document.querySelector('[data-detail-drawer]');
+        drawer.classList.remove('open');
+      }
+
+      function applyFilters() {
+        var searchEl = document.querySelector('[data-report-search]');
+        var statusEl = document.querySelector('[data-status-filter]');
+        var query = (searchEl && searchEl.value ? searchEl.value : '').toLowerCase();
+        var status = statusEl && statusEl.value ? statusEl.value : 'all';
+        var cells = document.querySelectorAll('[data-output-cell]');
+        var visible = 0;
+        cells.forEach(function (cell) {
+          var haystack = (cell.getAttribute('data-search') || '').toLowerCase();
+          var cellStatus = cell.getAttribute('data-status') || '';
+          var matchesSearch = query === '' || haystack.indexOf(query) !== -1;
+          var matchesStatus = status === 'all' || cellStatus === status;
+          var show = matchesSearch && matchesStatus;
+          cell.style.display = show ? '' : 'none';
+          if (show) {
+            visible += 1;
+          }
+        });
+        var countEl = document.querySelector('[data-visible-count]');
+        if (countEl) {
+          countEl.textContent = visible + ' of ' + cells.length + ' shown';
+        }
+        var empty = document.querySelector('[data-empty-state]');
+        if (empty) {
+          empty.style.display = visible === 0 ? 'block' : 'none';
+        }
+      }
+
+      applyFilters();
+    </script>
+  </body>
+</html>
