+import nunjucks from 'nunjucks';
+import fs from 'fs';
+const template = fs.readFileSync('src/tableOutput.html', 'utf-8');
+const env = nunjucks.configure({ autoescape: false, throwOnUndefined: false });
+const cells = [
+  { row:1, prompt:1, text:'Hello <b>world</b>', reason:'Looks good', error:'', status:'pass', statusLabel:'PASS', score:1, scoreLabel:'1.00', name:'input', vars:[{name:'input', value:'hi & <there>'}], promptText:'Say hi to {{input}}' },
+  { row:2, prompt:1, text:'', reason:'Evaluation failed', error:'provider timed out', status:'error', statusLabel:'ERROR', score:0, scoreLabel:'0.00', name:'input', vars:[{name:'input', value:'bye'}], promptText:'Say bye' },
+  { row:3, prompt:1, text:'nope', reason:'', error:'', status:'fail', statusLabel:'FAIL', score:0, scoreLabel:'0.00', name:'input', vars:[{name:'input', value:'x'}], promptText:'p' },
+];
+const out = env.renderString(template, {
+  config:{ description:'My Eval <Report>' },
+  cells,
+  summary:{ total:3, passCount:1, passRate:33.33333, passRateLabel:'33.3%' },
+});
+fs.writeFileSync('/tmp/out.html', out);
+const checks = [
+  ['data-output-cell="true"', out.includes('data-output-cell="true"')],
+  ['data-status="fail"', out.includes('data-status="fail"')],
+  ['data-status="error"', out.includes('data-status="error"')],
+  ['data-variable-name=', out.includes('data-variable-name="input"')],
+  ['status-pill pass', out.includes('class="status-pill pass"')],
+  ['>PASS<', out.includes('>PASS<')],
+  ['>FAIL<', out.includes('>FAIL<')],
+  ['metric-label Total Results', out.includes('<p class="metric-label">Total Results</p>')],
+  ['metric-value 3', /<p class="metric-value">3<\/p>/.test(out)],
+  ['passRate 33.3%', out.includes('33.3%')],
+  ['Score 1.00', out.includes('Score 1.00')],
+  ['View detail', out.includes('View detail')],
+  ['Result detail - row 1, prompt 1', out.includes('Result detail - row 1, prompt 1')],
+  ['Prompt header', out.includes('<h3>Prompt</h3>')],
+  ['Variables header', out.includes('<h3>Variables</h3>')],
+  ['empty state', out.includes('No rows match the current search and status filters.')],
+  ['data-report-search', out.includes('data-report-search')],
+  ['data-status-filter', out.includes('data-status-filter')],
+  ['data-visible-count', out.includes('data-visible-count')],
+  ['data-open-detail', out.includes('data-open-detail')],
+  ['data-detail-drawer', out.includes('data-detail-drawer')],
+  ['data-detail-template', out.includes('data-detail-template')],
+  ['appendVariableDetails(trigger)', out.includes('appendVariableDetails(trigger)')],
+  ['description escaped', out.includes('My Eval &lt;Report&gt;')],
+  ['error data-search exact', out.includes('data-search="ERROR 0.00 provider timed out Evaluation failed provider timed out"')],
+  ['NO forbidden for-loop', !out.includes('{% for variable in cell.variables %}')],
+  ['NO detail-variable-name span', !out.includes('<span class="detail-variable-name">')],
+  ['reason text present', out.includes('Looks good')],
+  ['output text escaped', out.includes('Hello &lt;b&gt;world&lt;/b&gt;')],
+];
+let ok=true;
+for (const [n,r] of checks){ if(!r){ok=false; console.log('FAIL:', n);} else console.log('ok  :', n); }
+console.log(ok ? '\nALL PASS' : '\nSOME FAILED');
